using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class OperationalInterference {static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var group=root.Find("B5_Operational_Detail");var go=new GameObject("OD_Temporary_Bounds_Probe");var proxy=go.AddComponent<BoxCollider>();var results=new List<object>();try{foreach(var f in group.GetComponentsInChildren<MeshFilter>()){if(f.name.Contains("WorkflowFloor"))continue;go.transform.SetPositionAndRotation(f.transform.position,f.transform.rotation);var b=f.sharedMesh.bounds;proxy.center=b.center;proxy.size=b.size;Physics.SyncTransforms();foreach(var c in Physics.OverlapBox(proxy.bounds.center,proxy.bounds.extents,Quaternion.identity,~0,QueryTriggerInteraction.Ignore)){if(c==proxy||c.transform.IsChildOf(f.transform)||!c.transform.IsChildOf(root)||!c.enabled)continue;Vector3 dir;float depth;if(Physics.ComputePenetration(proxy,go.transform.position,go.transform.rotation,c,c.transform.position,c.transform.rotation,out dir,out depth)&&depth>.04f)results.Add(new{a=P(f.transform),b=P(c.transform),depth});}}}finally{UnityEngine.Object.DestroyImmediate(go);}var report=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."))+"/Docs/검수/2026-11-08_B5_OperationalDetail/interference.json";File.WriteAllText(report,JsonConvert.SerializeObject(results,Formatting.Indented));return new{candidates=results.Count,results};}}
